lemmas.⊗-interchange:
{P Q R S T U : Obj} {p : P ⇒ Q} {r : R ⇒ S} {u : Q ⇒ T}
{v : S ⇒ U} →
u ⊗₁ v ∘ p ⊗₁ r ≈ (u ∘ p) ⊗₁ (v ∘ r)

lemma_normal.⊗-interchange:
{P Q R S T U : Obj} {p : P ⇒ Q} {r : R ⇒ S} {u : Q ⇒ T}
{v : S ⇒ U} →
⊗.F₁ (u , v) ∘ ⊗.F₁ (p , r) ≈ ⊗.F₁ (u ∘ p , v ∘ r)

lemmas.merge-bifunctor:
{A₁ B₁ C₁ A₂ B₂ C₂ : Obj} {u : B₁ ⇒ C₁} {u' : A₁ ⇒ B₁}
{v : B₂ ⇒ C₂} {v' : A₂ ⇒ B₂} →
u ⊗₁ v ∘ u' ⊗₁ v' ≈ (u ∘ u') ⊗₁ (v ∘ v')

lemma_normal.merge-bifunctor:
{A₁ B₁ C₁ A₂ B₂ C₂ : Obj} {u : B₁ ⇒ C₁} {u' : A₁ ⇒ B₁}
{v : B₂ ⇒ C₂} {v' : A₂ ⇒ B₂} →
⊗.F₁ (u , v) ∘ ⊗.F₁ (u' , v') ≈ ⊗.F₁ (u ∘ u' , v ∘ v')
